#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    if (n % 4 != 0 && n % 4 != 1) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> p(n + 1);
    for (int i = 1; i <= n / 2; i += 2) {
        p[i] = i + 1;
        p[i + 1] = n - i + 1;
        p[n - i + 1] = n - i;
        p[n - i] = i;
    }
    if (n % 2 == 1) {
        int mid = n / 2 + 1;
        p[mid] = mid;
    }
    for (int i = 1; i <= n; i++) {
        cout << p[i] << (i == n ? "\n" : " ");
    }
    return 0;
}
